// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Put actor's own stake below MinSum so the reference's MinSum gate fails,
        // while the mutant's missing gate still allows collection.
        uint256 minSum = c.MinSum();
        vm.assume(amount > 0);
        vm.assume(amount < minSum);
        vm.deal(actor, minSum);

        // Set a past unlock time: Put with 0 uses block.timestamp, so warp forward.
        vm.warp(2_000_000_000);
        vm.prank(actor);
        c.Put{value: amount}(0);

        uint256 balanceBefore = __invmut_c_Acc_balance(actor);

        // Advance time so block.timestamp > acc.unlockTime.
        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        try c.Collect(amount) {
            uint256 balanceAfter = __invmut_c_Acc_balance(actor);
            // Reference: since balanceBefore < MinSum, no state change must occur.
            // Mutant: balanceAfter becomes 0, so this assertion fails.
            assertTrue(balanceAfter == balanceBefore);
        } catch {
            // Reference reverts or silently no-ops; either way balance is unchanged.
            uint256 balanceAfter = __invmut_c_Acc_balance(actor);
            assertTrue(balanceAfter == balanceBefore);
        }
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
